-- Lote 3 dos exemplos resolvidos (conferido no Planalto em 08/10/2026). Entra under_review.
begin;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lavagem de Dinheiro", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Qual foi a infração penal de origem?", "Houve ocultação ou dissimulação do dinheiro?", "O processo depende do outro processo? (art. 2º)", "Há aumento ou redução de pena? (§§ 4º e 5º)"]}], "cases": [{"id": "lav-1", "title": "Dinheiro do jogo do bicho também pode ser lavado", "scenario": "Rafael ganha dinheiro com jogo do bicho, que é contravenção penal. Para esconder a origem, ele registra imóveis em nome de parentes.", "question": "Isso pode ser lavagem de dinheiro?", "steps": ["O art. 1º pune ocultar ou dissimular a natureza, origem, localização, disposição, movimentação ou propriedade de bens ou valores provenientes, direta ou indiretamente, de infração penal. A pena é reclusão de 3 a 10 anos e multa.", "Na redação original de 1998, só valia para uma lista fechada de crimes antecedentes. A Lei 12.683/2012 acabou com a lista.", "Hoje a origem pode ser qualquer infração penal, o que inclui crime e contravenção."], "conclusion": "Sim. Colocar imóveis em nome de parentes para esconder a origem do dinheiro é dissimulação, e a contravenção é infração penal suficiente como antecedente.", "variation": {"scenario": "E se o dinheiro viesse de uma dívida paga ou de uma herança?", "answer": "Sem origem em infração penal, não há lavagem. Falta o antecedente."}, "pitfall": "Achar que só vale para a lista antiga (tráfico, terrorismo etc.). Desde 2012 vale qualquer infração penal.", "articles": ["Art. 1"]}, {"id": "lav-2", "title": "Lavagem sem condenação pelo crime de origem", "scenario": "O MP denuncia Sônia por lavagem de dinheiro. O crime de que o dinheiro veio (um desvio) ainda não foi julgado, e o autor dele não foi identificado.", "question": "O processo por lavagem pode andar mesmo assim?", "steps": ["O art. 2º, II, diz que o processo da lavagem independe do processo da infração antecedente.", "O § 1º diz que a denúncia só precisa de indícios da infração antecedente, podendo o autor dela ser desconhecido, isento de pena ou com punibilidade extinta.", "O § 2º afasta o art. 366 do CPP: o acusado que não é encontrado é citado por edital e o processo segue."], "conclusion": "Sim. Bastam indícios do crime antecedente, e o processo por lavagem não precisa esperar pelo outro.", "variation": {"scenario": "E se não houvesse nenhum indício da infração antecedente?", "answer": "Aí falta justa causa para a denúncia, porque os indícios do antecedente são exigidos."}, "pitfall": "Achar que é preciso condenar primeiro o crime de origem. A lei exige apenas indícios.", "articles": ["Art. 2"]}, {"id": "lav-3", "title": "Criptomoedas e a delação", "scenario": "Tiago usa criptomoedas para esconder dinheiro de origem ilícita, de forma reiterada. Depois de preso, ele colabora espontaneamente com a investigação.", "question": "Como a pena é afetada?", "steps": ["O § 4º do art. 1º aumenta a pena de 1/3 a 2/3 se o crime é cometido de forma reiterada, por meio de organização criminosa ou com o uso de ativo virtual (redação da Lei 14.478/2022).", "O § 5º prevê redução de pena (de 1 a 2/3), regime aberto ou semiaberto e substituição por restritiva de direitos para quem colabora espontaneamente com as autoridades.", "Os dois efeitos podem aparecer no mesmo caso: aumento pelo meio e redução pela colaboração."], "conclusion": "A pena de Tiago sofre o aumento do § 4º (reiteração e ativo virtual) e pode ser reduzida pela colaboração espontânea do § 5º.", "variation": {"scenario": "E se Tiago só se arrependesse, sem ajudar a localizar os bens?", "answer": "A redução do § 5º depende de colaboração que ajude as autoridades. O arrependimento sem ajuda efetiva não basta."}, "pitfall": "Esquecer que o ativo virtual é causa de aumento desde 2022.", "articles": ["Art. 1"]}]}$json$::jsonb,
  $json$[{"title": "Lei 9.613/1998 — texto oficial (arts. 1º a 4º)", "url": "https://www.planalto.gov.br/ccivil_03/leis/l9613.htm", "checked_at": "2026-10-08T03:00:27Z"}]$json$::jsonb,
  '2026-10-08T03:00:27Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-lavagem-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei Maria da Penha", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["O fato é violência baseada no gênero?", "O ambiente é doméstico, familiar ou de relação íntima de afeto?", "Qual forma de violência? (art. 7º)", "Que medida protetiva e que consequência do descumprimento?"]}], "cases": [{"id": "mp-1", "title": "Sem morar junto também vale", "scenario": "Luana e Mário namoram há dois anos e nunca moraram juntos. Em uma briga, ele a agride e a ameaça por ciúmes.", "question": "A Lei Maria da Penha se aplica?", "steps": ["O art. 5º define violência doméstica e familiar contra a mulher como qualquer ação ou omissão baseada no gênero que cause morte, lesão, sofrimento físico, sexual ou psicológico e dano moral ou patrimonial.", "Isso ocorre no âmbito da unidade doméstica, da família ou de qualquer relação íntima de afeto, mesmo sem coabitação (inciso III).", "Luana e Mário têm relação íntima de afeto, e o ciúme mostra a violência baseada no gênero."], "conclusion": "Sim. A coabitação não é exigida: a relação íntima de afeto basta.", "variation": {"scenario": "E se a agressora fosse uma vizinha sem nenhuma relação familiar ou de afeto, por causa de uma briga de condomínio?", "answer": "Não há unidade doméstica, família ou relação íntima de afeto, e a violência não é baseada no gênero. A lei não se aplica."}, "pitfall": "Achar que é preciso morar junto. A relação íntima de afeto, mesmo sem coabitação, é suficiente.", "articles": ["Art. 5"]}, {"id": "mp-2", "title": "Medida protetiva sem boletim de ocorrência e o descumprimento", "scenario": "Carla procura a delegacia com medo do ex-companheiro. Ela ainda não quer abrir inquérito, mas pede proteção. O juiz concede medida protetiva. Depois, o ex se aproxima dela.", "question": "Ela precisa de boletim de ocorrência ou ação para a medida? E o que acontece com o ex?", "steps": ["O art. 19, §§ 4º a 6º (incluídos pela Lei 14.550/2023), diz que as medidas protetivas podem ser concedidas a partir do depoimento da ofendida, independem de tipificação penal, de ação penal ou cível, de inquérito ou de boletim de ocorrência, e vigoram enquanto persistir o risco.", "O art. 24-A pune quem descumpre a decisão que defere medidas protetivas, com reclusão de 2 a 5 anos e multa (pena elevada pela Lei 14.994/2024).", "Em flagrante, a fiança só pode ser concedida pelo juiz (§ 2º)."], "conclusion": "Carla não precisa de boletim, inquérito ou ação para obter a medida. O ex, ao se aproximar, comete o crime do art. 24-A.", "variation": {"scenario": "E se o ex adulterasse a tornozeleira eletrônica ou entrasse na área de exclusão monitorada?", "answer": "O art. 24-A, § 4º (Lei 15.383/2026) aumenta a pena de 1/3 até a metade nessa hipótese."}, "pitfall": "Achar que a medida depende de ação penal em curso. Ela é de urgência e independe disso.", "articles": ["Art. 19", "Art. 24-A"]}, {"id": "mp-3", "title": "Violência vicária: atingir a mãe por meio do filho", "scenario": "Depois da separação, Gilson ameaça e agride o filho de 8 anos, apenas para punir e atingir a ex-companheira.", "question": "A lei trata esse caso?", "steps": ["O art. 7º traz as formas de violência doméstica e familiar contra a mulher: física, psicológica, sexual, patrimonial e moral.", "O inciso VI (incluído pela Lei 15.384/2026) acrescentou a violência vicária: qualquer forma de violência praticada contra descendente, ascendente, dependente, enteado, parente, pessoa sob guarda ou responsabilidade da mulher, ou pessoa de sua rede de apoio, com vistas a atingi-la.", "Gilson agride o filho para atingir a ex. É a hipótese do inciso VI."], "conclusion": "Sim. É violência vicária, nova forma prevista no art. 7º, VI.", "variation": {"scenario": "E se Gilson agredisse o filho por motivo sem relação com a ex-companheira?", "answer": "Falta o elemento \"com vistas a atingi-la\". Ainda pode haver crime contra a criança, mas não a violência vicária."}, "pitfall": "Achar que a lei só protege a mulher da violência direta contra o próprio corpo.", "articles": ["Art. 7"]}]}$json$::jsonb,
  $json$[{"title": "Lei 11.340/2006 — texto oficial (arts. 5º, 7º, 19, 20 e 24-A)", "url": "https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11340.htm", "checked_at": "2026-10-08T03:00:27Z"}]$json$::jsonb,
  '2026-10-08T03:00:27Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-maria-penha-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei Henry Borel", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["É violência doméstica contra criança ou adolescente?", "Quem pode afastar o agressor, e em que ordem?", "Qual medida protetiva e qual prazo?", "Há reflexo no Código Penal? (prescrição, homicídio)"]}], "cases": [{"id": "hb-1", "title": "Quem afasta o agressor da casa", "scenario": "Em um município pequeno, que não é sede de comarca, uma criança é agredida pelo padrasto. Não há delegado na cidade naquele momento.", "question": "Quem pode determinar o afastamento imediato do agressor?", "steps": ["O art. 14 prevê o afastamento imediato do agressor do lar, determinado pelo juiz (I), pelo delegado, quando o município não é sede de comarca (II), ou pelo policial, quando não há delegado disponível no momento (III).", "O juiz é comunicado em 24 horas e decide em igual prazo.", "O § 3º diz que não será concedida liberdade provisória ao preso quando houver risco à vítima ou à efetividade da medida."], "conclusion": "O policial presente pode determinar o afastamento, e o juiz será comunicado em 24 horas para decidir em igual prazo.", "variation": {"scenario": "E se houvesse um delegado disponível, mas o município fosse sede de comarca?", "answer": "Cabe ao juiz determinar o afastamento (inciso I), sem a competência do delegado prevista para os municípios que não são sede de comarca."}, "pitfall": "Achar que só o juiz afasta o agressor. A lei prevê o delegado e o policial para situações de urgência.", "articles": ["Art. 14"]}, {"id": "hb-2", "title": "Prescrição de abuso contra criança só começa aos 18 anos", "scenario": "Uma menina de 8 anos sofre abuso sexual de um parente. O fato só é denunciado anos depois, quando ela já é adulta.", "question": "O prazo de prescrição conta a partir do fato?", "steps": ["A Lei Henry Borel acrescentou o inciso V ao art. 111 do Código Penal.", "Nos crimes contra a dignidade sexual ou que envolvam violência contra criança ou adolescente, a prescrição só começa a correr quando a vítima completa 18 anos, salvo se a ação penal já tiver sido proposta.", "Assim, o prazo não começa a contar enquanto a vítima é criança."], "conclusion": "Não. A prescrição só começa quando a vítima completa 18 anos, em regra.", "variation": {"scenario": "E se a denúncia já tivesse sido oferecida antes de ela completar 18 anos?", "answer": "A exceção \"salvo se a ação penal já tiver sido proposta\" se aplica, e vale a regra geral do início da contagem."}, "pitfall": "Contar a prescrição da data do fato. Para esses crimes, a regra mudou.", "articles": ["Art. 111"]}]}$json$::jsonb,
  $json$[{"title": "Lei 14.344/2022 — texto oficial (arts. 2º, 14 a 20 e alterações ao CP)", "url": "https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2022/lei/l14344.htm", "checked_at": "2026-10-08T03:00:27Z"}]$json$::jsonb,
  '2026-10-08T03:00:27Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-henry-borel-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei de Migração", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Quem é a pessoa para a lei? (art. 1º, § 1º)", "Qual princípio se aplica? (art. 3º)", "Qual medida de saída, se houver?", "Há garantia de direitos?"]}], "cases": [{"id": "mig-1", "title": "Imigrante, visitante, residente fronteiriço e apátrida", "scenario": "Quatro pessoas chegam ao Brasil: Ana vem para morar e trabalhar; Beto fica 15 dias de férias; Carla é nacional de país vizinho e mora em cidade de fronteira; Davi não tem nacionalidade reconhecida por nenhum Estado.", "question": "Como a lei classifica cada um?", "steps": ["O art. 1º, § 1º, define imigrante como a pessoa nacional de outro país ou apátrida que trabalha ou reside e se estabelece temporária ou definitivamente no Brasil. Ana é imigrante.", "Visitante é a pessoa que vem para estadia de curta duração, sem pretensão de se estabelecer. Beto é visitante.", "Residente fronteiriço é o nacional de país limítrofe ou apátrida que conserva residência habitual em município fronteiriço. Carla se encaixa. Apátrida é a pessoa que não é considerada nacional por nenhum Estado: Davi."], "conclusion": "Ana: imigrante. Beto: visitante. Carla: residente fronteiriço. Davi: apátrida.", "variation": {"scenario": "E se Beto decidisse ficar e trabalhar no Brasil?", "answer": "Ele passa a se enquadrar no conceito de imigrante, porque o que define a categoria é a intenção e a situação."}, "pitfall": "Confundir visitante (estadia curta) com imigrante (se estabelece no país).", "articles": ["Art. 1"]}, {"id": "mig-2", "title": "A política migratória e o princípio da não criminalização", "scenario": "Durante um debate, um aluno afirma que \"migrar já é crime\". O professor lembra que a política migratória brasileira tem princípios próprios.", "question": "O que a Lei de Migração diz sobre isso?", "steps": ["O art. 3º lista os princípios e diretrizes da política migratória brasileira, como a universalidade dos direitos humanos, o repúdio à xenofobia, ao racismo e a quaisquer formas de discriminação, a acolhida humanitária e a não criminalização da migração.", "Também prevê a garantia do direito à reunião familiar e o acesso igualitário a serviços públicos, educação, trabalho e moradia.", "O princípio da não criminalização da migração afasta a ideia de tratar o migrante, por esse fato, como criminoso."], "conclusion": "A afirmação está errada como regra geral: um dos princípios da política migratória é a não criminalização da migração.", "variation": {"scenario": "E se o estrangeiro cometesse um crime comum, como furto?", "answer": "Ele responde pelo furto como qualquer pessoa. O princípio protege contra criminalizar a migração, e não contra a responsabilização por outros crimes."}, "pitfall": "Misturar a condição de migrante com a prática de crimes. Os dois assuntos são tratados separadamente.", "articles": ["Art. 3"]}]}$json$::jsonb,
  $json$[{"title": "Lei 13.445/2017 — texto oficial (arts. 1º e 3º)", "url": "https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13445.htm", "checked_at": "2026-10-08T03:00:27Z"}]$json$::jsonb,
  '2026-10-08T03:00:27Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-migracao-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar os crimes do ECA", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Criança ou adolescente? (art. 2º)", "Qual conduta: produzir, vender, divulgar ou armazenar?", "Houve só acesso ou visualização? (art. 241-B, § 4º)", "Há exceção ou causa de aumento?"]}], "cases": [{"id": "eca-1", "title": "Doze anos exatos: criança ou adolescente?", "scenario": "Pedro faz 12 anos hoje. A mãe pergunta se ele ainda é criança para o ECA.", "question": "Pedro é criança ou adolescente?", "steps": ["O art. 2º considera criança a pessoa até 12 anos incompletos e adolescente aquela entre 12 e 18 anos.", "Quem completa 12 anos deixa de ter \"12 incompletos\".", "Logo, no dia em que faz 12 anos, Pedro passa a ser adolescente."], "conclusion": "Pedro é adolescente. A criança tem até 12 anos incompletos.", "variation": {"scenario": "E se Pedro tivesse 11 anos e 11 meses?", "answer": "Seria criança, porque ainda não completou 12 anos."}, "pitfall": "Achar que 12 anos ainda é criança. O limite é \"12 anos incompletos\".", "articles": ["Art. 2"]}, {"id": "eca-2", "title": "Só assistir, sem baixar, também é crime", "scenario": "Rui, por streaming, acessa e visualiza conteúdo de violência sexual contra criança, sem baixar nem salvar o arquivo, para satisfazer a própria lascívia.", "question": "Como a lei trata a conduta de Rui?", "steps": ["O art. 241-B pune adquirir, possuir ou armazenar esse conteúdo, com reclusão de 3 a 6 anos e multa na redação dada pela Lei 15.487/2026.", "O § 4º (novo) pune quem acessa ou visualiza o conteúdo por streaming, sem baixar ou armazenar, para satisfazer a própria lascívia ou a de outrem.", "Rui não armazenou, mas visualizou: a lacuna foi fechada em 2026."], "conclusion": "Rui comete o crime do art. 241-B, § 4º, mesmo sem baixar o arquivo.", "variation": {"scenario": "E se uma ONG guardasse o material apenas para entregá-lo às autoridades?", "answer": "O § 2º do art. 241-B afasta o crime quando a posse é para comunicar o fato às autoridades, como agente público, entidade de proteção ou provedor."}, "pitfall": "Achar que só quem guarda arquivo comete o crime. Desde 2026, o mero acesso por streaming também é punido.", "articles": ["Art. 241-B"]}, {"id": "eca-3", "title": "O adulto que leva o adolescente a cometer crime", "scenario": "Marcos, de 25 anos, convida Léo, de 16, para participar de um furto. Léo participa.", "question": "Marcos comete algum crime além do furto?", "steps": ["O art. 244-B pune corromper ou facilitar a corrupção de menor de 18 anos, com ele praticando infração penal ou induzindo-o a praticá-la. A pena é reclusão de 1 a 4 anos.", "O § 1º abrange os casos praticados por meios eletrônicos, como salas de bate-papo.", "O § 2º aumenta a pena em 1/3 se a infração induzida é crime hediondo."], "conclusion": "Sim. Marcos responde por furto e também por corrupção de menores (art. 244-B).", "variation": {"scenario": "E se a infração fosse um crime hediondo, convidado por mensagem de aplicativo?", "answer": "Aplica-se o § 2º, com aumento de 1/3, e a conduta pelo meio eletrônico se enquadra no § 1º."}, "pitfall": "Achar que o adulto só responde pelo crime em si. A corrupção de menores é crime autônomo.", "articles": ["Art. 244-B"]}]}$json$::jsonb,
  $json$[{"title": "Lei 8.069/1990 — texto oficial (arts. 2º, 240 a 241-B, 244-A e 244-B)", "url": "https://www.planalto.gov.br/ccivil_03/leis/l8069.htm", "checked_at": "2026-10-08T03:00:27Z"}]$json$::jsonb,
  '2026-10-08T03:00:27Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-eca-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar os direitos do preso na LEP", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Qual direito do art. 41 está em jogo?", "Quem pode restringi-lo? (§ 1º)", "Há vedação específica? (§ 2º)", "Qual é o controle do juiz?"]}], "cases": [{"id": "lep-1", "title": "O diretor pode suspender a visita?", "scenario": "Um diretor de presídio suspende, por conta própria e sem avisar o juiz, a visita do cônjuge de um preso, como castigo.", "question": "O diretor pode fazer isso?", "steps": ["O art. 41, X, garante ao preso a visita do cônjuge, da companheira, de parentes e de amigos em dias determinados.", "O § 1º (incluído pela Lei 14.994/2024) diz que os direitos dos incisos V, X e XV só podem ser suspensos ou restringidos por ato motivado do juiz da execução.", "Antes, bastava ato do diretor do estabelecimento. A mudança reforça o controle judicial."], "conclusion": "Não. Só o juiz da execução, por ato motivado, pode suspender ou restringir a visita.", "variation": {"scenario": "E se a restrição fosse de outro direito, como a alimentação?", "answer": "O § 1º cita os incisos V, X e XV; para os demais direitos, vale o que a lei dispuser. Confira a redação."}, "pitfall": "Achar que o diretor continua podendo suspender a visita. Desde 2024, é preciso ato motivado do juiz.", "articles": ["Art. 41"]}, {"id": "lep-2", "title": "Visita íntima para condenado por feminicídio", "scenario": "Um preso condenado por feminicídio pede à direção a visita íntima da companheira, alegando que é um direito do preso.", "question": "O pedido deve ser aceito?", "steps": ["O art. 41, X, assegura a visita do cônjuge, companheira, parentes e amigos.", "O § 2º (incluído pela Lei 14.994/2024) diz que o preso condenado por feminicídio não poderá usufruir do direito à visita íntima ou conjugal.", "O pedido esbarra diretamente nessa vedação."], "conclusion": "Não. A lei veda a visita íntima ao condenado por feminicídio.", "variation": {"scenario": "E se ele fosse condenado por furto?", "answer": "A vedação do § 2º é só para o condenado por feminicídio; nas demais condenações, a visita segue as regras gerais."}, "pitfall": "Achar que a vedação alcança todos os condenados por crimes violentos. Ela é específica para o feminicídio.", "articles": ["Art. 41"]}]}$json$::jsonb,
  $json$[{"title": "Lei 7.210/1984 — texto oficial (art. 41)", "url": "https://www.planalto.gov.br/ccivil_03/leis/l7210.htm", "checked_at": "2026-10-08T03:00:27Z"}]$json$::jsonb,
  '2026-10-08T03:00:27Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-lep-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar a Lei Antiterrorismo", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Há motivação e finalidade de terror social? (art. 2º)", "O ato é de manifestação política ou social? (§ 2º)", "A conduta é de integrar, financiar ou preparar? (arts. 3º, 5º e 6º)", "Qual a pena?"]}], "cases": [{"id": "ter-1", "title": "Manifestação com bloqueio de rua não é terrorismo", "scenario": "Um sindicato bloqueia uma avenida por algumas horas, com faixas e cartazes, reivindicando melhores salários. Houve transtorno no trânsito.", "question": "Isso é terrorismo?", "steps": ["O art. 2º define terrorismo como atos praticados por razões de xenofobia, discriminação ou preconceito de raça, cor, etnia ou religião, com a finalidade de provocar terror social ou generalizado, expondo a perigo pessoa, patrimônio, a incolumidade pública ou a paz pública.", "A pena é reclusão de 12 a 30 anos, além das sanções correspondentes à ameaça ou à violência.", "O § 2º diz que a lei não se aplica a manifestações políticas, movimentos sociais, sindicais e religiosos, quando têm propósito reivindicatório."], "conclusion": "Não. O protesto do sindicato, com propósito reivindicatório, é excluído pelo art. 2º, § 2º.", "variation": {"scenario": "E se, durante o protesto, alguns participantes usassem explosivos para provocar terror e ferir pessoas, por ódio racial?", "answer": "A cláusula do § 2º não protege atos que se encaixam no art. 2º, como o uso de explosivos com a finalidade de provocar terror social. Eles respondem individualmente."}, "pitfall": "Achar que todo bloqueio é terrorismo, ou que o protesto protege qualquer ato violento.", "articles": ["Art. 2"]}, {"id": "ter-2", "title": "Quem financia, quem integra e quem prepara", "scenario": "Bia envia dinheiro a um grupo terrorista para custear atentados, sem participar de nada. Caio integra o grupo. Ivo compra explosivos e planeja um atentado, mas é preso antes de executá-lo.", "question": "Que crime comete cada um?", "steps": ["O art. 6º pune quem financia o terrorismo, isto é, quem recebe, provê ou guarda recursos para a prática dos crimes da lei. A pena é reclusão de 15 a 30 anos.", "O art. 3º pune promover, constituir ou integrar organização terrorista, com reclusão de 5 a 8 anos e multa.", "O art. 5º pune os atos preparatórios com propósito inequívoco de consumar o terrorismo, com a pena do crime consumado reduzida de 1/4 a 1/2."], "conclusion": "Bia: financiamento (art. 6º). Caio: integrar organização terrorista (art. 3º). Ivo: atos preparatórios (art. 5º).", "variation": {"scenario": "E se Ivo desistisse voluntariamente do atentado antes de qualquer ato?", "answer": "Sem atos preparatórios com propósito inequívoco de consumação, a análise muda. Confira o texto do art. 5º e o entendimento sobre desistência voluntária."}, "pitfall": "Achar que sem atentado consumado não há crime. A lei pune a organização, o financiamento e os atos preparatórios.", "articles": ["Art. 3", "Art. 5", "Art. 6"]}]}$json$::jsonb,
  $json$[{"title": "Lei 13.260/2016 — texto oficial (arts. 2º, 3º, 5º e 6º)", "url": "https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13260.htm", "checked_at": "2026-10-08T03:00:27Z"}]$json$::jsonb,
  '2026-10-08T03:00:27Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-terrorismo-revisao'
on conflict (material_slug, version) do nothing;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  gen_random_uuid(),
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como analisar o tráfico de pessoas", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["Qual foi a ação? (agenciar, aliciar, transportar...)", "Qual o meio? (ameaça, violência, coação, fraude, abuso)", "Qual a finalidade? (órgãos, trabalho escravo, servidão, adoção ilegal, exploração sexual)", "Há aumento ou redução de pena?"]}], "cases": [{"id": "tp-1", "title": "Falsa oferta de emprego no exterior", "scenario": "Helena anuncia vagas de garçonete no exterior, engana as candidatas sobre as condições, paga as passagens e, quando elas chegam, as obriga à exploração sexual.", "question": "Que crime Helena comete e o que a lei exige?", "steps": ["O art. 149-A do CP (criado pela Lei 13.344/2016) pune agenciar, aliciar, recrutar, transportar, transferir, comprar, alojar ou acolher pessoa, mediante grave ameaça, violência, coação, fraude ou abuso, com a finalidade de remover órgãos, submeter a trabalho escravo ou servidão, adoção ilegal ou exploração sexual.", "A pena é reclusão de 4 a 8 anos e multa.", "Aqui há ação (aliciar e transportar), meio (fraude) e finalidade (exploração sexual)."], "conclusion": "Helena comete o tráfico de pessoas do art. 149-A. O crime exige ação, meio e finalidade.", "variation": {"scenario": "E se Helena apenas oferecesse o emprego, sem fraude, e a pessoa fosse trabalhar em condições normais?", "answer": "Falta o meio ilícito e a finalidade de exploração; não se configura o art. 149-A."}, "pitfall": "Procurar o crime na Lei 13.344: ela revogou os antigos arts. 231 e 231-A do CP e criou o art. 149-A, que está no Código Penal.", "articles": ["Art. 149-A"]}, {"id": "tp-2", "title": "Aumento e redução de pena no tráfico de pessoas", "scenario": "Dois agentes são condenados pelo art. 149-A: Joel, funcionário público, que traficou adolescentes, e Kátia, ré primária que não integra organização criminosa.", "question": "Como as penas de cada um são ajustadas?", "steps": ["O § 1º aumenta a pena de 1/3 até a metade se o crime é cometido por funcionário público no exercício das funções, contra criança, adolescente, idoso ou pessoa com deficiência, com abuso de relação de confiança, ou se a vítima é retirada do território nacional.", "O § 2º reduz a pena de 1/3 a 2/3 se o agente é primário e não integra organização criminosa.", "Joel se enquadra no aumento. Kátia, na redução."], "conclusion": "Joel: pena aumentada de 1/3 até a metade. Kátia: pena reduzida de 1/3 a 2/3.", "variation": {"scenario": "E se Kátia integrasse uma organização criminosa?", "answer": "A redução do § 2º é afastada, porque ela exige que o agente não integre organização criminosa."}, "pitfall": "Misturar as frações: aumento de 1/3 até a metade (§ 1º) e redução de 1/3 a 2/3 (§ 2º).", "articles": ["Art. 149-A"]}]}$json$::jsonb,
  $json$[{"title": "Código Penal, art. 149-A (Lei 13.344/2016)", "url": "https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm", "checked_at": "2026-10-08T03:00:27Z"}]$json$::jsonb,
  '2026-10-08T03:00:27Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-trafico-pessoas-revisao'
on conflict (material_slug, version) do nothing;

